<template><section class="teaching" v-loading="loading"><h2>课程任务与通知</h2><p v-if="!joined">加入后教师可查看你在本课程的任务提交与完成情况。</p><el-button v-if="!joined && student" :disabled="busy" @click="join">加入本课程</el-button><el-tabs><el-tab-pane label="教师任务"><article v-for="t in tasks" :key="t.id"><h3>{{ t.title }}</h3><p>{{ t.description }}</p><small>截止：{{ t.due_at ? new Date(t.due_at).toLocaleString('zh-CN') : '未设置' }}</small><p v-if="t.submission">状态：{{ t.submission.status==='graded'?'已评分':'待批改' }} · 分数：{{ t.submission.score ?? '待评分' }}</p><p v-if="t.submission?.feedback">教师反馈：{{ t.submission.feedback }}</p><template v-if="student"><el-input v-model="answers[t.id]" type="textarea" :rows="3" maxlength="10000" show-word-limit placeholder="填写任务提交内容"/><el-button :disabled="busy || !joined || expired(t)" @click="submit(t)">{{ expired(t)?'已截止':t.submission?'重新提交（原评分将清空）':'提交任务' }}</el-button></template></article><el-empty v-if="!tasks.length" description="暂无教师任务"/></el-tab-pane><el-tab-pane label="课程通知"><article v-for="n in notices" :key="n.id"><h3>{{ n.is_pinned?'置顶 · ':'' }}{{ n.title }}</h3><p>{{ n.content }}</p><small>{{ new Date(n.created_at).toLocaleString('zh-CN') }}</small></article><el-empty v-if="!notices.length" description="暂无课程通知"/></el-tab-pane></el-tabs></section></template>
<script setup>
import {ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {api} from '../utils/api'
const props=defineProps({courseId:Number}),tasks=ref([]),notices=ref([]),answers=ref({}),loading=ref(false),busy=ref(false),joined=ref(false)
const student=(JSON.parse(localStorage.getItem('user')||'{}').role||'student')==='student'
const expired=t=>t.due_at&&Date.parse(t.due_at)<Date.now()
let version=0
async function load(){const current=++version,id=props.courseId;tasks.value=[];notices.value=[];answers.value={};joined.value=false;if(!id)return;loading.value=true;try{const [t,n,m]=await Promise.all([api(`/courses/${id}/teacher-tasks`),api(`/courses/${id}/announcements`),api(`/courses/${id}/membership`)]);if(current!==version)return;tasks.value=t;notices.value=n;joined.value=m.joined;answers.value=Object.fromEntries(t.map(x=>[x.id,x.submission?.content||'']))}catch(e){ElMessage.error(e.message)}finally{if(current===version)loading.value=false}}
async function join(){busy.value=true;try{await api(`/courses/${props.courseId}/join`,{method:'POST'});await load();ElMessage.success('已加入课程')}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function submit(t){if(!answers.value[t.id]?.trim())return ElMessage.warning('请填写提交内容');busy.value=true;try{await api(`/teacher-tasks/${t.id}/submit`,{method:'POST',body:JSON.stringify({content:answers.value[t.id]})});ElMessage.success('已提交');await load()}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
watch(()=>props.courseId,load,{immediate:true})
</script>
<style scoped>.teaching{border:1px solid #eeddd3;border-radius:18px;padding:20px;margin:20px 0;background:#fffdfb;color:#633e2e}article{border-bottom:1px solid #eeddd3;padding:15px 0}p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7}.el-button{margin-top:12px}</style>
